---RefreshUI
---@param equipDojo EquipDojo
---@param index number
---@param unlockTipText string 解锁提示文字
function UICultivateSubAttrNodeNode:RefreshUI(equipDojo, index, unlockTipText, isMainAttr)

    local key = isMainAttr and "mainAttrId" or string.format("attr%sId", index)
    local attrAdditionId = checkNumber(equipDojo[key])
    local isOwnAttr = attrAdditionId > 0

    KTool.SetActive(self.AttrNode.gameObject, isOwnAttr)
    KTool.SetActive(self.LevelTip.gameObject, not isOwnAttr)
    if isOwnAttr then
        key = isMainAttr and "mainAttrNum" or string.format("attr%sNum", index)
        local attrNum = equipDojo[key]
        self:RefreshAttrNode(attrAdditionId, attrNum)
    else
        self.LevelTip.text = unlockTipText
    end

end

function UICultivateSubAttrNodeNode:RefreshAttrNode(attrAdditionId, attrNum, isMainAttr)
    ---@type BasicAttrAdditionVo
    local attrAdditionVo = cardConfMgr:GetBasicAttrAdditionById(attrAdditionId)
    local basicVo = cardConfMgr:GetBasicAttrByBasicAttrAdditionId(attrAdditionId)
    self.AttrNameText.text = basicVo.name
    -- self.AttrNameText.textComp.text = attrAdditionVo.attrAdditionName
    -- self.AttrNameText.Status = isMainAttr and 2 or 1
    self.AttrNumText.text = attribute_format(attrAdditionVo.isConversion, attrNum)
    -- self.AttrNumText.Status  = isMainAttr and 2 or 1
end

function UICultivateSubAttrNodeNode:RefreshBackgroundShowState(isShow)
    KTool.SetActive(self.Background.gameObject, isShow)
end

